// === Tab: mySketch ===
/* 
 * Griglia reattiva alla MUSICA – p5.sound
 * - Ampiezza e bassi modulano distorsione, spessore, colore e scie
 * - Beat detector semplice per “accenti” visivi
 * - Buffer offscreen per scie persistenti
 * - File MP3 locale via file picker o path predefinito
 * - Commenti in italiano
 */

let dots = [];          // matrice dei punti [i][j]
let pg;                 // buffer offscreen per le scie
let modeAttract = true; // true=attrazione, false=repulsione

// ==== AUDIO ====
const DEFAULT_MP3 = ''; // es. '/assets/track.mp3' oppure lascia vuoto e usa il file picker
let song, amp, fft;
let level = 0;          // ampiezza istantanea 0..~0.5
let bass = 0;           // energia bassi 0..255
// Beat detection minimale
let beatCutoff = 0;
let beatDecay = 0.97;
let beatHoldFrames = 18;
let beatFrames = 0;

// ==== CONFIG BASE (valori “a riposo”) ====
const CFG = {
  numb: 55,            // punti per lato
  dist: 50,            // raggio d'influenza mouse (base)
  distortion: 15,      // ampiezza distorsione (base)
  trailAlpha: 18,      // dissolvenza scie per frame
  strokeMin: 0.4,      // spessore minimo
  strokeMax: 6,        // spessore massimo vicino al mouse
  wobbleAmp: 0.75,     // wobble da Perlin
  wobbleScale: 0.01,   // scala spaziale rumore
  wobbleTime: 0.01,    // velocità temporale rumore
  damping: 0.86        // smorzamento velocità
};

// ==== PARAMETRI LIVE (modulati dalla musica ad ogni frame) ====
const PARAMS = {
  dist: CFG.dist,
  distortion: CFG.distortion,
  trailAlpha: CFG.trailAlpha,
  strokeMin: CFG.strokeMin,
  strokeMax: CFG.strokeMax,
  wobbleAmp: CFG.wobbleAmp,
  hueSpeed: 0.12       // velocità variazione tonalità di base
};

function preload() {
  if (DEFAULT_MP3) song = loadSound(DEFAULT_MP3);
}

function setup() {
  initCanvas();
  initAudioUI();
  initGrid();
  initAudioNodes();
}

function windowResized() {
  initCanvas();
  initGrid();
}

// Canvas + buffer scie
function initCanvas() {
  const s = max(windowWidth, windowHeight);
  createCanvas(s, s);
  pixelDensity(1);
  colorMode(HSB, 360, 100, 100, 255);

  pg = createGraphics(width, height);
  pg.pixelDensity(1);
  pg.colorMode(HSB, 360, 100, 100, 255);
  pg.background(0, 0, 0); // nero
}

// UI: pulsanti e file picker
function initAudioUI() {
  createButton('Play / Pause')
    .mousePressed(() => {
      if (!song) return; // serve un MP3
      if (!song.isPlaying()) song.loop();
      else song.pause();
    })
    .position(10, 10);

  createButton('Carica MP3')
    .mousePressed(() => {
      createFileInput(handleFile, false).position(110, 10);
    })
    .position(110, 10);
}

// Instanzia amp/fft
function initAudioNodes() {
  amp = new p5.Amplitude(0.9);  // smoothing alto
  fft = new p5.FFT(0.9, 1024);  // smoothing, 1024 bins
}

// File picker handler
function handleFile(file) {
  if (!file || file.type !== 'audio') return;
  if (song) {
    song.stop();
    song.disconnect();
  }
  song = loadSound(file.data, () => song.loop());
}

// Griglia centrata responsive
function initGrid() {
  dots = [];
  const usable = width * 0.92;                 // margine intorno
  const step = usable / (CFG.numb - 1);        // spacing
  const offset = (width - usable) / 2;

  const seed = floor(random(1e9));
  randomSeed(seed);
  noiseSeed(seed);

  for (let i = 0; i < CFG.numb; i++) {
    dots[i] = [];
    for (let j = 0; j < CFG.numb; j++) {
      const x = offset + i * step;
      const y = offset + j * step;
      dots[i][j] = new Dot(x, y, i, j);
    }
  }
}

// Click: reset griglia e scie
function mouseClicked() {
  initGrid();
  pg.background(0, 0, 0);
}

function draw() {
  // === Analisi audio ===
  if (amp && fft) {
    level = amp.getLevel();           // tipico 0..0.3
    const spec = fft.analyze();
    bass = fft.getEnergy('bass');     // 0..255
    updateBeat(level);
  } else {
    level = 0; bass = 0;
  }

  // === Mappature musicali → PARAMS ===
  // Bassi spingono distorsione e spessore
  PARAMS.dist       = CFG.dist + map(bass, 60, 220, 0, 35, true);
  PARAMS.distortion = CFG.distortion + map(bass, 60, 220, 0, 18, true);
  PARAMS.strokeMax  = CFG.strokeMax + map(bass, 60, 220, 0, 2.5, true);

  // Ampiezza alza il wobble e accelera il colore
  PARAMS.wobbleAmp  = CFG.wobbleAmp + map(level, 0, 0.35, 0, 1.0, true);
  PARAMS.hueSpeed   = 0.12 + map(level, 0, 0.35, 0, 0.4, true);

  // Scie più “lente” quando la musica è quieta, più “lampate” sui picchi
  PARAMS.trailAlpha = CFG.trailAlpha + map(level, 0, 0.35, -8, 10, true);

  // Dissolve scie sul buffer
  pg.noStroke();
  pg.fill(0, 0, 0, PARAMS.trailAlpha);
  pg.rect(0, 0, pg.width, pg.height);

  // Vettore mouse
  const m = createVector((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))));

  // Aggiorna e disegna i punti
  for (let i = 0; i < CFG.numb; i++) {
    for (let j = 0; j < CFG.numb; j++) {
      dots[i][j].update(m);
      dots[i][j].render(pg);
    }
  }

  // Flash leggero sui beat
  if (beatFrames > 0) {
    pg.noStroke();
    pg.fill(0, 0, 100, 12); // velo bianco
    pg.rect(0, 0, width, height);
    beatFrames--;
  }

  // Proietta buffer
  image(pg, 0, 0, width, height);
}

// Tasti rapidi
function keyPressed() {
  if (key === ' ') (isLooping() ? noLoop() : loop());
  if (key === 'A' || key === 'a') modeAttract = !modeAttract;
  if (key === 'R' || key === 'r') initGrid();
  if (key === 'C' || key === 'c') pg.background(0, 0, 0);
}

/* ===== Beat detection semplice =====
   Trigger quando il livello supera una soglia adattiva.
*/
function updateBeat(lvl) {
  const minLevel = 0.06;
  if (lvl > beatCutoff && lvl > minLevel && beatFrames === 0) {
    onBeat(lvl);
    beatCutoff = lvl * 1.1;
    beatFrames = beatHoldFrames;
  } else {
    beatCutoff *= beatDecay;
    beatCutoff = max(beatCutoff, minLevel);
  }
}

function onBeat(lvl) {
  // Piccolo “accento”: spingi ancora la distorsione istantaneamente
  PARAMS.distortion += map(lvl, 0.06, 0.35, 2, 8, true);
  // Inverti per 1 frame l’attrazione per un effetto “rimbalzo”
  modeAttract = !modeAttract;
  setTimeout(() => { modeAttract = !modeAttract; }, 60);
}

/* ==========================
   Classe Dot
   - Ogni punto ha origine, posizione, velocità
   - Si muove con molla verso/da il mouse
   - Wobble da Perlin aggiunge organicità
   - Colore/spessore variano con distanza e audio
   ========================== */
class Dot {
  constructor(x, y, i, j) {
    this.pos = createVector(x, y);
    this.origin = this.pos.copy();
    this.vel = createVector(0, 0);
    this.i = i; this.j = j;
    this.hue0 = map(i, 0, CFG.numb - 1, 180, 360) + map(j, 0, CFG.numb - 1, -60, 60);
    this.stepCache = 0; // per micro jitter uniforme
  }

  update(m) {
    // Distanza mouse-origin e curva morbida 0..PI
    const toMouse = p5.Vector.sub(m, this.origin);
    const d = toMouse.mag();
    const c = map(d, 0, PARAMS.dist, 0, PI, true);

    // Direzione verso/da mouse
    const dir = toMouse.copy().normalize().mult(modeAttract ? 1 : -1);

    // Ampiezza distorsione modulata da musica
    const amp = PARAMS.distortion * sin(c);

    // Bersaglio elastico
    const target = p5.Vector.add(this.origin, dir.mult(amp));

    // Molla: più vicino = guadagno maggiore
    const spring = p5.Vector.sub(target, this.pos);
    const k = map(d, 0, width, 0.2, 0.02, true);
    spring.mult(k);

    // Wobble Perlin
    const t = frameCount * CFG.wobbleTime;
    const nx = noise(this.origin.x * CFG.wobbleScale, this.origin.y * CFG.wobbleScale, t);
    const ang = nx * TWO_PI + this.stepCache * 0.015;
    const wobble = createVector(cos(ang), sin(ang)).mult(PARAMS.wobbleAmp);

    // Accumula e integra
    this.vel.add(spring).add(wobble);
    this.vel.mult(CFG.damping);
    this.pos.add(this.vel);

    this.stepCache++;
  }

  render(g) {
    // Spessore: più spesso vicino al mouse + bass boost
    const dm = dist(this.pos.x, this.pos.y, (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))));
    const near = dm < PARAMS.dist;
    const baseSW = near
      ? map(dm, 0, PARAMS.dist, PARAMS.strokeMax, CFG.strokeMin, true)
      : map(min(dm, width), 0, width, 2, CFG.strokeMin, true);
    const sw = baseSW + map(bass, 60, 220, 0, 1.2, true);

    // Colore: tonalità animata col tempo e ampiezza
    const hue = (this.hue0 + frameCount * PARAMS.hueSpeed) % 360;
    const bri = near ? 100 : 70;

    g.stroke(hue, 80, bri, 255);
    g.strokeWeight(sw);
    g.point(this.pos.x, this.pos.y);
  }
}

